import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"技能状态栏","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/actionbar.md","filePath":"modules/skills/actionbar.md","lastUpdated":0}`),a={name:`modules/skills/actionbar.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="技能状态栏" tabindex="-1">技能状态栏 <a class="header-anchor" href="#技能状态栏" aria-label="Permalink to “技能状态栏”">​</a></h1><p>配置技能状态栏 (Action Bar) 要定下这些: 显示什么内容, 有哪些模板变量, 刷新间隔怎么设, 以及强制延迟怎么用</p><p>技能状态栏就是玩家施法时显示在屏幕底部的那行提示, 用来展示技能槽, 触发器, 强制延迟和当前状态. 这样玩家不用老是打开 GUI 去看自己绑了什么</p><h2 id="配置位置" tabindex="-1">配置位置 <a class="header-anchor" href="#配置位置" aria-label="Permalink to “配置位置”">​</a></h2><p>状态栏的配置在 <code>config.yml</code> 的 <code>actionbar</code> 节点:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actionbar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 是否启用技能状态 ActionBar</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 刷新间隔, 单位 tick; 小于 1 按 1 处理</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  refresh_interval_ticks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 施法模式下的显示模板</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_cast_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;施法模式&lt;/gold&gt; %slot_1% %slot_2% %slot_3% &lt;gray&gt;延迟:&lt;/gray&gt; %forced_delay%&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 非施法模式模板; 空值回退源码默认文本, 不关闭显示</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_idle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>actionbar.enabled</code></td><td>boolean</td><td>否</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>是否启用状态栏刷新. 关掉后就不再启动刷新任务了</td></tr><tr><td><code>actionbar.refresh_interval_ticks</code></td><td>integer</td><td>否</td><td><code>10</code></td><td>≥ 1, 小于 1 按 1</td><td>刷新间隔, 单位 tick (20 tick ≈ 1 秒)</td></tr><tr><td><code>actionbar.template_cast_mode</code></td><td>string</td><td>否</td><td><code>&amp;aCast Mode &amp;7| %slot_display%</code></td><td>MiniMessage 文本</td><td>施法模式开启时用的模板. 留空或全是空白时, 回退成内置默认模板</td></tr><tr><td><code>actionbar.template_idle</code></td><td>string</td><td>否</td><td><code>&amp;7Idle</code></td><td>MiniMessage 文本</td><td>非施法模式的模板. 留空或全是空白时, 回退成内置默认值</td></tr></tbody></table><div class="important custom-block"><p class="custom-block-title custom-block-title-default">IMPORTANT</p><p>目前的实现只在玩家处于施法模式并且技能档案已加载时才推送 Action Bar: 玩家退出施法模式或档案没加载时会直接跳过刷新, <code>template_idle</code> 不会发给玩家. 这个键仍然会被解析, 并作为回退的默认值留着</p></div><h2 id="模板变量" tabindex="-1">模板变量 <a class="header-anchor" href="#模板变量" aria-label="Permalink to “模板变量”">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>%slot_display%</code></td><td>所有槽位合并后的展示文本, 槽位之间用空格分隔</td></tr><tr><td><code>%slot_1%</code> ~ <code>%slot_n%</code></td><td>指定槽位的展示文本. <code>n</code> 取决于玩家的技能槽数量 (<code>slots.default_count</code>); <code>%slot_1%</code> 对应索引 0 的槽位</td></tr><tr><td><code>%forced_delay%</code></td><td>全局强制施法延迟的剩余时间, 格式是 <code>1.5s</code>; 没有延迟时是 <code>0s</code></td></tr></tbody></table><p>槽位的展示文本由几部分拼起来: 技能绑定, 触发器显示名, 冷却状态和空槽状态. 空槽用语言文件里的 <code>gui.slot_empty_short</code>, 触发器显示名来自 <code>triggers.&lt;id&gt;.display_name</code>, 没绑触发器时用 <code>gui.trigger_unbound_short</code></p><h2 id="强制延迟" tabindex="-1">强制延迟 <a class="header-anchor" href="#强制延迟" aria-label="Permalink to “强制延迟”">​</a></h2><p><code>cast_timing</code> 控制释放成功后写进去的全局强制延迟; 剩余时间用上面的 <code>%forced_delay%</code> 展示给玩家看</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">cast_timing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 成功施法后的全局延迟, 单位 tick; 0 关闭</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  forced_global_cast_delay_ticks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>cast_timing.forced_global_cast_delay_ticks</code></td><td>integer</td><td>否</td><td><code>0</code></td><td>≥ 0, 负数按 0</td><td>成功施法后写进去的全局强制延迟, 单位 tick. 延迟期间新的施法尝试会以 <code>cast.forced_delay</code> 失败. <code>0</code> 表示关闭</td></tr></tbody></table><h2 id="与施法模式的关系" tabindex="-1">与施法模式的关系 <a class="header-anchor" href="#与施法模式的关系" aria-label="Permalink to “与施法模式的关系”">​</a></h2><p>状态栏只在施法模式开启时才刷新. 施法模式的入口键, 启用开关和重登恢复策略写在 <code>config.yml &gt; cast_mode</code>, 见 <a href="./triggers.html#施法模式">触发器 - 施法模式</a></p><ul><li>施法模式开启后, 主动触发器才会监听左键, 右键, Q 键, 数字键这些服务端能看到的操作</li><li>玩家重登时若 <code>cast_mode.restore_last_state_on_join: true</code>, 会恢复上次的施法模式状态, 状态栏刷新也随之恢复</li></ul><h2 id="推荐模板" tabindex="-1">推荐模板 <a class="header-anchor" href="#推荐模板" aria-label="Permalink to “推荐模板”">​</a></h2><h3 id="简洁模板" tabindex="-1">简洁模板 <a class="header-anchor" href="#简洁模板" aria-label="Permalink to “简洁模板”">​</a></h3><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actionbar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_cast_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;施法&lt;/gold&gt; %slot_display%&quot;</span></span></code></pre></div><p>技能槽比较少的服务器, 用它最合适</p><h3 id="带延迟提示" tabindex="-1">带延迟提示 <a class="header-anchor" href="#带延迟提示" aria-label="Permalink to “带延迟提示”">​</a></h3><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actionbar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template_cast_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;施法模式&lt;/gold&gt; %slot_1% %slot_2% %slot_3% &lt;gray&gt;延迟:&lt;/gray&gt; %forced_delay%&quot;</span></span></code></pre></div><p>你启用了 <code>cast_timing.forced_global_cast_delay_ticks</code> 的话, 用它最合适</p><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to “使用建议”">​</a></h2><ul><li>如果你服务器上已经有战斗提示, 区域提示, 任务提示等 Action Bar 输出, 最好统一规划一下谁优先显示</li><li>技能槽数量比较多时, 建议用 <code>%slot_display%</code> 或拆成好几组显示, 免得一行太长</li></ul><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to “排查建议”">​</a></h2><ul><li>状态栏不显示: 检查 <code>actionbar.enabled</code> 是否为 true, 你是否已进入施法模式, 技能档案是否已加载</li><li>槽位显示为空: 检查你是否拥有技能, 是否已绑定槽位, 技能来源是否已同步</li><li>延迟一直不变: 检查 <code>cast_timing.forced_global_cast_delay_ticks</code> 是否配置异常, 技能释放是否成功写入延迟</li><li>与其他 Action Bar 插件冲突: 调整 <code>actionbar.refresh_interval_ticks</code></li></ul>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};